"""Stage cover ZIPs and finalize their database records after upload verification.

Cover IDs have ten digits: four for the million-cover item, two for the
10,000-cover batch, and four for the image within that batch.
"""

import datetime
import fcntl
import os
import subprocess
import time
import zipfile
from contextlib import contextmanager

from openlibrary.coverstore import config, db

SIZES = ('', 's', 'm', 'l')


def _size(size):
    size = size.lower()
    if size not in SIZES:
        raise ValueError(f'Invalid size: {size}')
    return size


class Cover:
    def __init__(self, attributes):
        self.attributes = attributes
        self.id = int(attributes['id'])

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        number = int(cover_id)
        if not 0 <= number < 10_000_000_000:
            raise ValueError('Cover ID must fit in ten digits')
        padded = f'{number:010d}'
        return padded[:4], padded[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        if protocol not in ('http', 'https'):
            raise ValueError('Invalid protocol')
        size = _size(size)
        ext = ext.lstrip('.')
        if not ext or '/' in ext or '\\' in ext:
            raise ValueError('Invalid extension')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        suffix = f'-{size.upper()}' if size else ''
        return (f'{protocol}://archive.org/download/{item}/'
                f'{item}_{batch_id}.zip/{int(cover_id):010d}{suffix}.{ext}')

    def local_files(self):
        result = {}
        for size in SIZES:
            field = f'filename_{size}' if size else 'filename'
            filename = self.attributes.get(field)
            if not filename:
                return None
            path = os.path.join(config.data_root, 'localdisk', filename)
            if not os.path.isfile(path):
                return None
            result[size] = path
        return result


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (int(start_id) // 10_000 + 1) * 10_000 - 1

    def pending(self, start_id=8_000_000):
        return self.db.select('cover', where='id >= $start_id AND failed=false '
                              'AND (archived=false OR archived IS NULL)',
                              vars={'start_id': start_id}, order='id', limit=1)

    def batch_covers(self, item_id, batch_id):
        start_id = int(item_id) * 1_000_000 + int(batch_id) * 10_000
        end_id = self._get_batch_end_id(start_id)
        return self.db.select('cover', where='id >= $start_id AND id <= $end_id '
                              'AND failed=false AND (archived=false OR archived IS NULL)',
                              vars={'start_id': start_id, 'end_id': end_id}, order='id')

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext='jpg'):
        database = db.getdb()
        transaction = database.transaction()
        try:
            rows = CoverDB().batch_covers(item_id, batch_id)
            for row in rows:
                database.update('cover', where='id=$cover_id AND failed=false',
                    vars={'cover_id': row.id}, archived=True, uploaded=True,
                    filename=Cover.get_cover_url(row.id, ext=ext),
                    filename_s=Cover.get_cover_url(row.id, 's', ext),
                    filename_m=Cover.get_cover_url(row.id, 'm', ext),
                    filename_l=Cover.get_cover_url(row.id, 'l', ext))
            transaction.commit()
        except Exception:
            transaction.rollback()
            raise


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = item_id, batch_id
        self.size = None if size is None else _size(size)
        self._norm_ids()

    def _norm_ids(self):
        item_id, batch_id = int(self.item_id), int(self.batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('Invalid item or batch ID')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls(item_id, batch_id)._norm_ids()
        size = _size(size)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        return os.path.join('items', item, f'{item}_{batch_id}.{ext.lstrip(".")}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @contextmanager
    def lock(self):
        item_id, batch_id = self._norm_ids()
        lock_dir = os.path.join(config.data_root, 'items', '.locks')
        os.makedirs(lock_dir, exist_ok=True)
        with open(os.path.join(lock_dir, f'{item_id}_{batch_id}.lock'), 'a+b') as file:
            fcntl.flock(file, fcntl.LOCK_EX | fcntl.LOCK_NB)
            try:
                yield
            finally:
                fcntl.flock(file, fcntl.LOCK_UN)

    def finalize(self, start_id=None, test=False):
        item_id, batch_id = self._norm_ids()
        paths = {size: self.get_abspath(item_id, batch_id, size) for size in SIZES}
        if not all(os.path.isfile(path) for path in paths.values()):
            return False
        rows = list(CoverDB().batch_covers(item_id, batch_id))
        if not rows:
            return True
        for size, path in paths.items():
            suffix = f'-{size.upper()}' if size else ''
            expected = {f'{row.id:010d}{suffix}.jpg' for row in rows}
            with zipfile.ZipFile(path) as archive:
                if not expected.issubset(set(archive.namelist())):
                    return False
        if not test:
            CoverDB.update_completed_batch(item_id, batch_id)
            for row in rows:
                files = Cover(row).local_files()
                if files:
                    for path in files.values():
                        os.remove(path)
            for path in paths.values():
                os.remove(path)
        return True

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        sizes = SIZES if self.size is None else (self.size,)
        item_id, batch_id = self._norm_ids()
        uploader = uploader or Uploader()
        with self.lock():
            paths = {size: self.get_abspath(item_id, batch_id, size) for size in sizes}
            if not all(os.path.isfile(path) for path in paths.values()):
                return False
            for size, path in paths.items():
                item = f'{size}_covers_{item_id}' if size else f'covers_{item_id}'
                if not uploader.is_uploaded(item, os.path.basename(path)):
                    if upload and not test:
                        uploader.upload(item, [path])
                    if not uploader.is_uploaded(item, os.path.basename(path)):
                        return False
            if finalize:
                return self.size is None and self.finalize(test=test)
            return True


class ZipManager:
    def __init__(self):
        self.zipfiles = {}
        self.added = {}

    def get_zipfile(self, name):
        stem = name.split('.', 1)[0]
        cover_id = int(stem.split('-', 1)[0])
        size = stem.split('-', 1)[1].lower() if '-' in stem else ''
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            self.zipfiles[path] = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED)
            self.added[path] = set(self.zipfiles[path].namelist())
        return self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        archive = self.get_zipfile(name)
        if name in self.added[archive.filename]:
            return archive.filename
        dt = datetime.datetime.fromtimestamp(mtime).timetuple()[:6]
        info = zipfile.ZipInfo(name, date_time=max(dt, (1980, 1, 1, 0, 0, 0)))
        info.compress_type = zipfile.ZIP_STORED
        with open(filepath, 'rb') as source, archive.open(info, 'w') as target:
            while chunk := source.read(1024 * 1024):
                target.write(chunk)
        self.added[archive.filename].add(name)
        return archive.filename

    def close(self):
        for archive in self.zipfiles.values():
            archive.close()
        self.zipfiles.clear()
        self.added.clear()


def open_zipfile(name):
    stem = name.split('.', 1)[0]
    cover_id = int(stem.split('-', 1)[0])
    size = stem.split('-', 1)[1].lower() if '-' in stem else ''
    item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
    path = Batch.get_abspath(item_id, batch_id, size)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED)


def get_zipfile(name):
    return open_zipfile(name)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith('.jpg') for name in archive.namelist())


class Uploader:
    @staticmethod
    def upload(itemname: str, filepaths: list[str]):
        return subprocess.run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                              text=True, capture_output=True, check=True)

    @staticmethod
    def is_uploaded(item: str, zip_filename: str, verbose=False):
        result = subprocess.run(['ia', 'list', item], text=True, capture_output=True, check=True)
        found = zip_filename in result.stdout.splitlines()
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


def archive(test=True, start_id=8_000_000, limit=10_000):
    """Stage one batch. Local references remain authoritative until finalization."""
    coverdb = CoverDB()
    pending = list(coverdb.pending(start_id))
    if not pending:
        return None
    item_id, batch_id = Cover.id_to_item_and_batch_id(pending[0].id)
    batch = Batch(item_id, batch_id)
    with batch.lock():
        manager = ZipManager()
        try:
            for row in list(coverdb.batch_covers(item_id, batch_id))[:limit]:
                files = Cover(row).local_files()
                if not files:
                    if not test:
                        coverdb.db.update('cover', where='id=$cover_id AND failed=false',
                                          vars={'cover_id': row.id}, failed=True)
                    continue
                created = row.created
                if isinstance(created, str):
                    from infogami.infobase import utils
                    created = utils.parse_datetime(created)
                mtime = time.mktime(created.timetuple())
                if not test:
                    for size, path in files.items():
                        suffix = f'-{size.upper()}' if size else ''
                        manager.add_file(f'{row.id:010d}{suffix}.jpg', path, mtime)
        finally:
            manager.close()
    return batch

